function normalizeConversationState(state){
 const next=state&&typeof state==='object'?state:{seen:0,length:0,memory:[]};
 if(!Array.isArray(next.memory))next.memory=[];
 next.memory=next.memory.map(m=>m?.role==='assistant'&&typeof m.text==='string'?{...m,text:safeDisplayReply(m.text)}:m);
 if(!Number.isFinite(next.seen))next.seen=0;
 if(!Number.isFinite(next.length))next.length=next.memory.length;
 next.relationship=relationshipSnapshot(next.relationship ?? next.affection ?? 0,settings?.relationshipPace);
 delete next.affection;
 return next;
}
function relationshipSummary(){
 return relationshipSnapshot(conversation?.relationship||0,settings?.relationshipPace);
}
function scaleRelationshipDelta(kind,delta){
 let amount=Math.max(-3,Math.min(3,Math.round(Number(delta)||0)));
 const pace=settings?.relationshipPace||'normal';
 if(kind!=='tension'&&amount>0){
  if(pace==='easy')amount=Math.min(3,amount+1);
  if(pace==='slow')amount=Math.max(1,amount-1);
 }
 return amount;
}
function applyRelationshipUpdate(reply={}){
 if(settings.relationshipSystem===false)return;
 const rel=relationshipSummary();
 const trust=rel.trust + scaleRelationshipDelta('trust',reply.trustDelta||0);
 const romance=rel.romance + scaleRelationshipDelta('romance',reply.romanceDelta||0);
 const tension=rel.tension + scaleRelationshipDelta('tension',reply.tensionDelta||0);
 conversation.relationship=relationshipSnapshot({
  ...rel,
  trust,romance,tension,
  dating:typeof reply.dating==='boolean'?reply.dating:rel.dating,
  confessed:typeof reply.confessed==='boolean'?reply.confessed:rel.confessed,
  rejections:rel.rejections + (reply.rejectedProposal?1:0),
  note:reply.relationshipNote||rel.note
 },settings.relationshipPace);
}

