function friendlyError(e){let cause=e,diagnostic='';for(let i=0;i<3&&cause;i++,cause=cause.cause)diagnostic+=' '+String(cause.message||'');if(/401|unauthorized|invalid.api.key/i.test(diagnostic))return 'Модель отклонила ключ (401). Проверь ключ выбранного подключения в SillyTavern.';if(/429|rate.limit|quota|insufficient.credit/i.test(diagnostic))return 'Лимит или баланс провайдера исчерпан. Проверь выбранную модель и попробуй позже.';if(/403|forbidden/i.test(diagnostic))return 'Провайдер запретил запрос (403). Проверь доступ к выбранной модели.';if(/404|model.not.found/i.test(diagnostic))return 'Не найден адрес API или модель (404). Проверь профиль подключения.';if(e.message?.startsWith('Модель')||e.message?.startsWith('Ответ')||e.message?.startsWith('В ответе')||e.message?.startsWith('Текущее')||e.message?.startsWith('Профиль'))return e.message;return 'Не удалось получить ответ. Проверь подключение, модель, ключ и баланс в SillyTavern, затем нажми «Повторить».';}
