function field(label,key,type='text',options=null){const wrapper=document.createElement('label');wrapper.className='qtc-setting';const caption=document.createElement('span');caption.textContent=label;wrapper.append(caption);let input;if(options){input=document.createElement('select');for(const [value,text] of options){const opt=document.createElement('option');opt.value=value;opt.textContent=text;input.append(opt);}}else if(type==='textarea'){input=document.createElement('textarea');input.rows=3;input.maxLength=5000;}else{input=document.createElement('input');input.type=type;if(type==='text')input.maxLength=500;}input.dataset.setting=key;input.value=settings[key]??'';if(type==='checkbox')input.checked=!!settings[key];input.onchange=async()=>{let value=type==='checkbox'?input.checked:input.value;if(['size','bottom','interval','contextMessages','contextChars','maxTokens','opacity','textSpeed','fontSize','dialogueWidth'].includes(key)){const bounds={size:[45,120],bottom:[16,260],interval:[2,100],contextMessages:[2,80],contextChars:[2000,32000],maxTokens:[150,2400],opacity:[65,100],textSpeed:[0,100],fontSize:[16,28],dialogueWidth:[340,900]}[key];value=Math.max(bounds[0],Math.min(bounds[1],(Number.isFinite(Number(value))?Number(value):DEFAULTS[key])));input.value=value;}settings[key]=value;invalidate();persistSettings();if(key==='placement'){welcome=value!=='chat';titleOpen=welcome;}if(['source','character','follow'].includes(key)){await refresh();await openSettings();}else if(['ownName','personality','manner','relation'].includes(key)){scheduleRefresh();}else{render();}if(key==='source')prefs.querySelector('[data-own-fields]').hidden=value!=='own';};wrapper.append(input);return wrapper;}
