 const pick=document.createElement('select');pick.setAttribute('aria-label','Эмоция для разметки');for(const e of available){const o=document.createElement('option');o.value=e;o.textContent=EMOTIONS[e];pick.append(o);}pick.value=emotion;dialog.append(pick);
 const controls=document.createElement('div');controls.className='qtc-zone-controls';dialog.append(controls);
 for(const [id,label] of Object.entries(BODY_ZONES))button(controls,label,()=>{selected=id;paint();});
 const canvas=document.createElement('div');canvas.className='qtc-zone-canvas';const img=document.createElement('img');img.loading='lazy';img.decoding='async';img.alt='Нарисуй прямоугольник выбранной области';img.draggable=false;canvas.append(img);const overlay=document.createElement('div');overlay.className='qtc-zone-overlay';canvas.append(overlay);dialog.append(canvas);
 const state=document.createElement('p');state.setAttribute('role','status');dialog.append(state);
 const numeric=document.createElement('div');numeric.className='qtc-zone-numeric';dialog.append(numeric);const inputs={};for(const [key,label] of [['x','Слева, %'],['y','Сверху, %'],['w','Ширина, %'],['h','Высота, %']]){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type='number';i.min=0;i.max=100;i.step=1;i.onchange=()=>{let z=draft.find(z=>z.id===selected);if(!z){z={id:selected,x:0,y:0,w:.2,h:.2};draft.push(z);}z[key]=Math.max(0,Math.min(1,(Number(i.value)||0)/100));z.w=Math.min(z.w,1-z.x);z.h=Math.min(z.h,1-z.y);paint();};inputs[key]=i;l.append(i);numeric.append(l);}
