 const presets=document.createElement('div');presets.className='qtc-zone-controls';dialog.append(presets);button(presets,'Поясной портрет',()=>{draft=presetZones('portrait');paint();});button(presets,'Полный рост',()=>{draft=presetZones('full');paint();});button(presets,'Убрать выбранную зону',()=>{draft=draft.filter(z=>z.id!==selected);paint();});
