function applyDialogTheme(dialog){if(!dialog||!settings)return;const stamp=JSON.stringify([settings.theme,settings.panel,settings.ink,settings.accent,settings.performance]);if(dialogStamps.get(dialog)===stamp)return;dialogStamps.set(dialog,stamp);dialog.classList.toggle('qtc-economy',settings.performance!=='balanced');dialog.dataset.theme=settings.theme;for(const k of ['panel','ink','accent'])dialog.style.setProperty('--qtc-'+k,settings[k]);}
function renderChoices(){const box=$('choices');if(!box)return;const stamp=JSON.stringify([settings.suggestReplies,replyChoices,busy]);if(stamp===choicesStamp)return;choicesStamp=stamp;box.replaceChildren();box.hidden=!settings.suggestReplies||!replyChoices.length;for(const text of replyChoices){const b=button(box,text,()=>{replyChoices=[];ask({kind:'message',text});});b.disabled=busy;}}
function addTitleUploader(container,status,targetId){const label=document.createElement('h3');label.textContent='Отдельная PNG для стартового экрана';container.append(label);note(container,'Не заменяет эмоции. Если не загрузить, на старте используется обычная PNG.');const input=document.createElement('input');input.type='file';input.accept='image/png,.png';input.hidden=true;container.append(input);const upload=button(container,titleImageURL?'Заменить стартовую PNG':'Добавить стартовую PNG',()=>input.click());upload.disabled=!targetId;input.onchange=async()=>{try{await uploadImage('title',input.files[0],targetId);status.textContent='Стартовый портрет сохранён.';await openSettings();}catch(e){status.textContent=e.message;}input.value='';};if(titleImageURL){const image=document.createElement('img');image.src=titleImageURL;image.alt='Стартовый портрет';image.className='qtc-start-preview';container.append(image);button(container,'Удалить стартовую PNG',async()=>{await store.remove('png:'+targetId+':title');await store.remove('preview1280:'+targetId+':title');if(identity?.id===targetId){await loadImages(targetId);render();}await openSettings();});}}
function addAuthoring(container){const box=document.createElement('div');box.className='qtc-authoring';container.append(box);const title=document.createElement('h3');title.textContent='Придумать вместе с ИИ';box.append(title);note(box,'Достаточно идеи в одном поле. Запрос использует подключение компаньона; чаты и PNG для создания описания не отправляются.');const idea=document.createElement('textarea');idea.placeholder='Идея или пожелания: например, язвительная подруга, которая любит старое кино';idea.setAttribute('aria-label','Пожелания для ИИ');idea.maxLength=2000;box.append(idea);const status=document.createElement('p');status.setAttribute('role','status');box.append(status);const preview=document.createElement('div');preview.className='qtc-author-preview';box.append(preview);
 async function generate(mode){if(authorBusy||busy||currentPending||isHostBusy()){status.textContent='Дождись завершения текущего запроса.';return;}const profile=settings.activeCompanion,original=Object.fromEntries(Object.keys(CHARACTER_FIELDS).map(k=>[k,settings[k]||''])),selectedConnection=settings.profile;const prompt=authorPrompt(original,idea.value,mode);authorBusy=true;fill.disabled=develop.disabled=true;status.textContent='Создаю описание…';preview.replaceChildren();const abort=new AbortController();let timeout;
 try{const raw=await Promise.race([selectedConnection?profileRequest(ctx(),prompt,abort.signal,900):currentRequest(ctx(),prompt,900),new Promise((_,reject)=>{timeout=setTimeout(()=>{abort.abort();reject(new Error('Ответ занимает слишком много времени. Попробуй позже.'));},90000);})]);if(settings.activeCompanion!==profile){status.textContent='Профиль изменился. Результат не применён.';return;}const draft=mergeCharacter(original,parseCharacter(raw),mode);status.textContent='Черновик готов. Можно поправить поля перед применением.';const editors={};for(const [key,label] of Object.entries(CHARACTER_FIELDS)){const wrapper=document.createElement('label');wrapper.className='qtc-setting';const caption=document.createElement('span');caption.textContent=label;const input=document.createElement(key==='ownName'?'input':'textarea');input.value=draft[key];input.maxLength=key==='ownName'?80:1500;editors[key]=input;wrapper.append(caption,input);preview.append(wrapper);}button(preview,'Применить описание',async()=>{if(settings.activeCompanion!==profile||Object.keys(original).some(k=>(settings[k]||'')!==original[k])){status.textContent='Профиль или исходные поля изменились. Создай новый черновик, чтобы не затереть правки.';return;}for(const k of Object.keys(editors))settings[k]=editors[k].value.trim();persistSettings();await refresh();await openSettings();});button(preview,'Отбросить',()=>{preview.replaceChildren();status.textContent='Черновик удалён. Исходные поля сохранены.';});}
 catch(e){status.textContent=/формат|полей персонажа|описание/.test(e.message)?e.message:friendlyError(e);}finally{clearTimeout(timeout);authorBusy=false;fill.disabled=develop.disabled=false;}}
 const fill=button(box,'Заполнить пустое',()=>generate('empty')),develop=button(box,'Развить описание',()=>generate('develop'));
}

function renderTheme(){const stamp=JSON.stringify([settings.theme,settings.dialogueWidth,settings.fontSize,settings.themedFont,settings.effects,settings.themeNames,settings.performance,settings.sceneBackground,settings.panelSize]);if(stamp===themeStamp)return;themeStamp=stamp;root.classList.toggle('qtc-economy',settings.performance!=='balanced');const t=themeOf(settings.theme);root.style.setProperty('--qtc-dialogue-width',(settings.dialogueWidth||520)+'px');root.style.setProperty('--qtc-font-size',(settings.fontSize||18)+'px');root.classList.toggle('qtc-plain-font',settings.themedFont===false);root.classList.toggle('qtc-no-effects',settings.effects===false);root.classList.toggle('qtc-no-scene',settings.sceneBackground===false);root.dataset.themeNames=String(settings.themeNames!==false);$('titleWordmark').hidden=settings.themeNames===false;$('themeTitle').textContent=settings.themeNames!==false?t.title:'Тихая таверна';$('themeSubtitle').textContent=settings.themeNames!==false?t.subtitle:'Личная история · твоя таверна';const ids=['startMeeting','enterTavern','profilesMenu','memoryMenu','galleryMenu'];for(let i=0;i<ids.length;i++){const b=$(ids[i]);b.textContent=settings.themeNames!==false?t.labels[i]:PLAIN_LABELS[i];b.title=PLAIN_LABELS[i];b.setAttribute('aria-label',PLAIN_LABELS[i]+(settings.themeNames!==false?' — '+t.labels[i]:''));}for(const [id,index] of [['panelProfiles',2],['panelHistory',3]]){const b=$(id);b.textContent=settings.themeNames!==false?t.labels[index]:PLAIN_LABELS[index];b.title=PLAIN_LABELS[index];}root.dataset.effect=t.effect;const words=ACTION_WORDS[settings.themeNames!==false?settings.theme:'plain']||ACTION_WORDS.plain;root.querySelectorAll('.qtc-actions [data-act]').forEach((b,i)=>{if(!words[i])return;b.dataset.act=words[i][1];b.innerHTML=icon(['cup','heart','star','kiss','hand'][i])+' '+words[i][0];});}
async function exportBackup(){if(!store.entries)throw new Error('Хранилище пока недоступно.');saveProfile(settings);if(scope)await store.set('memory:'+scope,structuredClone(conversation));const rows=await store.entries();const encoded=[];for(const [key,value] of rows){if(key==='settings-backup'||key.startsWith('preview1280:'))continue;if(value instanceof Blob){const bytes=new Uint8Array(await value.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));encoded.push({key,blob:btoa(binary),type:value.type});}else encoded.push({key,value});}const payload={format:'quiet-tavern-backup',version:1,created:new Date().toISOString(),settings:structuredClone(settings),records:encoded};const url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='quiet-tavern-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function addBackupImport(container,status){const input=document.createElement('input');input.type='file';input.accept='application/json,.json';input.hidden=true;container.append(input);button(container,'Восстановить из резервной копии',()=>input.click());const preview=document.createElement('div');container.append(preview);input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;if(file.size>200*1024*1024)throw new Error('Копия слишком большая: максимум 200 МБ.');const backup=validateBackup(JSON.parse(await file.text()));preview.replaceChildren();note(preview,'Копия: '+backup.settings.companionProfiles.length+' профилей, '+backup.records.filter(r=>r.key.startsWith('png:')).length+' PNG. Восстановление переключит расширение на данные этой копии. Текущие записи останутся в прежнем локальном хранилище; сначала скачай их копию, если захочешь вернуться.');const apply=button(preview,'Восстановить и переключиться',async()=>{apply.disabled=true;try{if(busy||currentPending||authorBusy)throw new Error('Сначала дождись завершения запросов.');const restored=structuredClone(backup.settings),nextStore=new LocalStore(crypto.randomUUID());for(const r of backup.records){let value=r.value;if('blob' in r){const binary=atob(r.blob),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));if(![137,80,78,71,13,10,26,10].every((x,i)=>bytes[i]===x))throw new Error('Повреждён PNG в копии.');value=new Blob([bytes],{type:'image/png'});}await nextStore.set(r.key,value);}invalidate();clearTimeout(saveTimer);states.clear();scope='';identity=null;Object.assign(settings,structuredClone(DEFAULTS),restored,{storageId:nextStore.scope,savedAt:Date.now()});store=nextStore;ensureProfiles(settings);migrateThemes(settings);restoreProfile(settings);if(!settings.panelLayoutVersion){for(const profile of settings.companionProfiles){const v=profile.values||{};if(Number(v.dialogueWidth)===660)v.dialogueWidth=520;if(!v.panelSize)v.panelSize='compact';}if(Number(settings.dialogueWidth)===660)settings.dialogueWidth=520;if(!settings.panelSize)settings.panelSize='compact';settings.panelLayoutVersion=1;}persistSettings();muted=settings.muted;titleOpen=true;welcome=true;await refresh();await openSettings();}catch(e){status.textContent=e.message;apply.disabled=false;}});}catch(e){status.textContent=e.message;}input.value='';};}
